// Answers a private message when it arrives outside opening hours, at most once per COOLDOWN_HOURS per person.
const OPEN_DAYS = [1, 2, 3, 4, 5]; // Monday to Friday (Sunday is 0)
const OPEN_FROM = 9;               // 09:00
const OPEN_UNTIL = 18;             // 18:00
const COOLDOWN_HOURS = 12;

const event = msg.payload;
if (event.type !== 'message.received') {
    return null;
}
const data = event.data || {};
const sender = data.from || {};
if ((data.to && data.to.group_id) || !sender.number) {
    return null;
}
const when = new Date(event.created_at || Date.now());
const hour = when.getHours() + when.getMinutes() / 60;
if (OPEN_DAYS.includes(when.getDay()) && hour >= OPEN_FROM && hour < OPEN_UNTIL) {
    return null;
}
const answeredAt = flow.get('answeredAt') || {};
if (when.getTime() - (answeredAt[sender.number] || 0) < COOLDOWN_HOURS * 3600 * 1000) {
    return null;
}
answeredAt[sender.number] = when.getTime();
flow.set('answeredAt', answeredAt);
// Never more than 60 answers an hour in all, so a flood from many numbers cannot use up your message allowance.
const MAX_ALL = 60;
const nowMs = event.created_at ? new Date(event.created_at).getTime() : Date.now();
const lastHour = (flow.get('sentAll') || []).filter((t) => t > nowMs - 3600 * 1000);
if (lastHour.length >= MAX_ALL) {
    return null;
}
lastHour.push(nowMs);
flow.set('sentAll', lastHour);
msg.to = '+' + sender.number;
msg.number = event.number_alias || 'main';
msg.payload = 'Thanks for your message. We are closed now and we answer from Monday to Friday, ' + OPEN_FROM + ':00 to ' + OPEN_UNTIL + ':00.';
return msg;
